import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"🧭 03 · 学习路线总览","description":"","frontmatter":{},"headers":[],"relativePath":"00-导论与学习哲学/03-学习路线总览.md","filePath":"00-导论与学习哲学/03-学习路线总览.md","lastUpdated":1786806808000}'),r={name:"00-导论与学习哲学/03-学习路线总览.md"};function l(i,t,c,n,h,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="🧭-03-·-学习路线总览" tabindex="-1">🧭 03 · 学习路线总览 <a class="header-anchor" href="#🧭-03-·-学习路线总览" aria-label="Permalink to &quot;🧭 03 · 学习路线总览&quot;">​</a></h1><blockquote><p>不同背景、不同目标的人，学习路径差异巨大。本章给你 4 条可执行的路线 + 时间预估 + 里程碑自检。</p></blockquote><hr><h2 id="路线-a-零基础转行-ai-应用开发-最稳妥、岗位最多" tabindex="-1">路线 A：零基础转行 AI 应用开发（最稳妥、岗位最多） <a class="header-anchor" href="#路线-a-零基础转行-ai-应用开发-最稳妥、岗位最多" aria-label="Permalink to &quot;路线 A：零基础转行 AI 应用开发（最稳妥、岗位最多）&quot;">​</a></h2><p><strong>目标</strong>：6-9 个月，达到 AI 应用开发/算法应用工程师水平，能独立做 RAG/Agent 项目。</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>内容</th><th>里程碑（能做什么）</th></tr></thead><tbody><tr><td>A1 基础</td><td>1-2 月</td><td>Python 扎实、线性代数/概率入门、Git/Linux</td><td>写脚本、调 API</td></tr><tr><td>A2 LLM 入门</td><td>1-2 月</td><td><code>01-LLM</code> 基础篇、Prompt 工程、API 调用</td><td>搭一个问答机器人</td></tr><tr><td>A3 RAG/Agent</td><td>2 月</td><td><code>03-AI Agent</code>、<code>08-AI应用开发</code></td><td>做带检索+工具的 Agent</td></tr><tr><td>A4 工程化</td><td>1-2 月</td><td>向量库、推理部署、LLMOps、<code>09-面试</code></td><td>上线一个可演示项目</td></tr><tr><td>A5 求职</td><td>持续</td><td>简历、真题、模拟面试</td><td>拿到 offer</td></tr></tbody></table><p>➡️ 重点看：<code>06-开发岗</code> → <code>08-AI应用开发</code> → <code>03-AI Agent</code></p><hr><h2 id="路线-b-科班研究生冲算法岗-深度优先" tabindex="-1">路线 B：科班研究生冲算法岗（深度优先） <a class="header-anchor" href="#路线-b-科班研究生冲算法岗-深度优先" aria-label="Permalink to &quot;路线 B：科班研究生冲算法岗（深度优先）&quot;">​</a></h2><p><strong>目标</strong>：吃透模型原理与推导，能答「深问 + 手撕」。</p><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>里程碑</th></tr></thead><tbody><tr><td>B1 根基</td><td><code>04-传统深度学习</code> 全、数学</td><td>推导 BP、CNN、RNN</td></tr><tr><td>B2 大模型</td><td><code>01-LLM</code> 全（Transformer 推导、注意力、位置编码、RLHF/DPO 推导）</td><td>手写 MHA/RoPE/LoRA</td></tr><tr><td>B3 生成+Agent</td><td><code>02-生成式</code>、<code>03-AI Agent</code></td><td>理解 Diffusion 与 Agent 范式</td></tr><tr><td>B4 前沿</td><td><code>05-前沿与具身</code>、顶会论文</td><td>能讲清一个前沿方向</td></tr><tr><td>B5 实战</td><td>复现论文 / Kaggle / 实习</td><td>有产出证明深度</td></tr></tbody></table><p>➡️ 重点看：<code>01-LLM</code> → <code>04-传统深度学习</code> → <code>算法岗真题</code></p><hr><h2 id="路线-c-后端-前端工程师转-ai-工程杠杆" tabindex="-1">路线 C：后端/前端工程师转 AI（工程杠杆） <a class="header-anchor" href="#路线-c-后端-前端工程师转-ai-工程杠杆" aria-label="Permalink to &quot;路线 C：后端/前端工程师转 AI（工程杠杆）&quot;">​</a></h2><p><strong>目标</strong>：用现有工程能力 + AI 应用知识，切入高薪 AI 应用岗。</p><ul><li>不必重学数学，直接 <code>08-AI应用开发</code> + <code>03-AI Agent</code></li><li>用你的语言优势（Java/Go/前端）做 AI 平台/中间件，差异化竞争</li><li>补 <code>01-LLM</code> 的「原理够用层」即可（不必推导，但要知道为什么）</li></ul><p>➡️ 重点看：<code>07-开发岗</code> → <code>08-AI应用开发</code> → <code>开发岗真题</code></p><hr><h2 id="路线-d-在职-做长期职业规划-战略视角" tabindex="-1">路线 D：在职，做长期职业规划（战略视角） <a class="header-anchor" href="#路线-d-在职-做长期职业规划-战略视角" aria-label="Permalink to &quot;路线 D：在职，做长期职业规划（战略视角）&quot;">​</a></h2><ul><li>先读 <code>00-导论</code>（本质判断）+ <code>10-职业发展与资源</code></li><li>用「跨周期技术地图」盘点自己的技能，补齐 L0/L1 短板</li><li>每季度定向补一个 L2 技术，保持对 L4 的嗅觉</li><li>结合 <code>10-薪资爆料/公司指南</code> 做 1-3 年职业决策</li></ul><hr><h2 id="自我检测的「过关清单」" tabindex="-1">自我检测的「过关清单」 <a class="header-anchor" href="#自我检测的「过关清单」" aria-label="Permalink to &quot;自我检测的「过关清单」&quot;">​</a></h2><p><strong>LLM 算法岗最低过关线</strong>（能流畅讲清 + 推导）：</p><ul><li>[ ] Transformer 结构、自注意力公式与复杂度</li><li>[ ] 位置编码（绝对/相对/RoPE）思想与差异</li><li>[ ] 预训练目标（MLM/CLM）、Scaling Law 直觉</li><li>[ ] 微调：LoRA 原理、与全参微调的代价对比</li><li>[ ] 对齐：RLHF 三阶段、PPO vs DPO 区别</li><li>[ ] 解码：贪心/采样/温度/top-p、KV Cache</li><li>[ ] 推理优化：量化、KV Cache、投机解码、MoE</li></ul><p><strong>AI 应用开发最低过关线</strong>：</p><ul><li>[ ] 能独立搭一个 RAG（分块/嵌入/检索/重排/生成）</li><li>[ ] 能设计一个 Agent（ReAct、工具、记忆）</li><li>[ ] 会选型和用向量库、了解 LLMOps 基础</li><li>[ ] 能做成本/延迟/质量的权衡</li></ul><hr><h2 id="时间管理建议" tabindex="-1">时间管理建议 <a class="header-anchor" href="#时间管理建议" aria-label="Permalink to &quot;时间管理建议&quot;">​</a></h2><ul><li><strong>每日 2 小时 &gt; 周末 14 小时</strong>：AI 知识密度高，靠持续而非突击。</li><li><strong>70/20/10 法则</strong>：70% 时间学核心（L0/L1/L2），20% 动手项目，10% 看前沿。</li><li><strong>产出驱动</strong>：每学一个模块，写一篇笔记或一个 demo，发到 GitHub/博客。</li></ul><hr><p>➡️ 返回：<a href="./../00-导论与学习哲学/README">00-导论与学习哲学 README</a> ｜ 进入：<a href="./../01-算法岗-AIGC与LLM/README">01-算法岗-AIGC与LLM</a></p>',31)])])}const L=d(r,[["render",l]]);export{p as __pageData,L as default};
